import {toast} from 'sonner';
import {useLab} from './lab-context';
import {useDeviceState} from './device-state';
import {modules,byId,canView,canAct,canRecordAct,recordsFor,authorizedRecords,fieldAccess,money,personFor,type ModuleDef,type RecordData} from './model';
import {purchaseCommitment,bakeryBalance,businessRules,validateConfig,metricCatalog,metricValue,type ConfigVersion} from './enterprise-contract';
